<template><view class="page"><text class="brand">安康</text><text class="title">欢迎回来</text><text class="sub">登录后查看家人的健康与照护动态</text><view class="card"><input v-model="phone" class="input" type="number" maxlength="11" placeholder="手机号"/><input v-model="password" class="input" type="password" placeholder="密码"/><button class="primary" @tap="login">登录</button><view class="links"><text @tap="forgot">忘记密码</text><text @tap="register">注册账号</text></view></view></view></template><script>export default{data(){return{phone:'',password:''}},methods:{login(){if(!/^1\d{10}$/.test(this.phone)||this.password.length<6){return uni.showToast({title:'请输入正确账号信息',icon:'none'})}uni.showToast({title:'登录成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:'/pages/family/home/index'}),500)},forgot(){uni.navigateTo({url:'/pages/forgot-password/index'})},register(){uni.navigateTo({url:'/pages/register/index'})}}}</script><style scoped>.page{min-height:100vh;padding:150rpx 38rpx;background:linear-gradient(180deg,#eef4ec,#fbfaf6);box-sizing:border-box}.brand{display:block;font-size:60rpx;font-weight:900;color:#285b48}.title{display:block;margin-top:20rpx;font-size:42rpx;font-weight:900}.sub{display:block;margin-top:12rpx;color:#7b857f;font-size:24rpx}.card{margin-top:42rpx;padding:30rpx;background:#fff;border-radius:30rpx}.input{height:88rpx;margin-bottom:20rpx;padding:0 22rpx;background:#f4f6f3;border-radius:18rpx}.primary{background:#315f4b;color:#fff;border-radius:20rpx}.links{display:flex;justify-content:space-between;margin-top:24rpx;color:#55705f;font-size:23rpx}</style>